interface WorldMapBackdropProps {
  className?: string;
  /** Map fill color. */
  color?: string;
  /** 1 = base composition (default). Below 1 pads the viewBox so the map renders smaller/more zoomed out, still centered and covering the frame. */
  zoom?: number;
}

const BASE_X = -240;
const BASE_Y = 374.26;
const BASE_W = 2480;
const BASE_H = 1049.63;

export function WorldMapBackdrop({ className, color = '#D8D2C3', zoom = 1 }: WorldMapBackdropProps) {
  const w = BASE_W / zoom;
  const h = BASE_H / zoom;
  const x = BASE_X - (w - BASE_W) / 2;
  const y = BASE_Y - (h - BASE_H) / 2;

  return (
    <svg
      viewBox={`${x} ${y} ${w} ${h}`}
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
      className={className}
    >
      <path d={WORLD_PATH} fill={color} />
    </svg>
  );
}
